      if (r.error) { toast(r.error, true); return; }
      fill(el("mk_herd"), herdOpts(r.herds), "Select herd…");
      el("mk_herd")._company = r.company; el("mk_herd")._operator = r.employee;
    });
    function recalc() {
      var net = num(el("mk_total").value) - num(el("mk_discard").value);
