    }
    ["mk_total", "mk_discard", "mk_price"].forEach(function (n) { el(n).addEventListener("input", recalc); });
    el("mk_submit").addEventListener("click", function () {
      var p = {
        herd: el("mk_herd").value, milking_time: el("mk_time").value, recording_date: el("mk_date").value,
        cows_milked: el("mk_cows").value, total_yield_kg: el("mk_total").value, discarded_kg: el("mk_discard").value || 0,
        price_per_kg: el("mk_price").value || 0, protein_percent: el("mk_protein").value,
        discard_reason: el("mk_discard_reason").value,
        bulk_scc: el("mk_scc").value, remarks: el("mk_remarks").value,
        company: el("mk_herd")._company, operator: el("mk_herd")._operator,
