  // ---- calf numbers ------------------------------------------------------
  // The number is the register's, not the operator's: A for a heifer, B for a
  // bull, three digits, and the year of birth. It is assigned rather than typed,
  // because a number typed twice is two animals sharing an identity.
  function pad3(n) { return ("00" + n).slice(-3); }

  function calfNumbersInForm(except) {
    var used = [];
    qa('[data-el="cv_calves"] tbody tr').forEach(function (tr) {
      if (tr === except) return;
      var v = (tr.querySelector(".c_tag").value || "").trim().toUpperCase();
      if (v) used.push(v);
    });
    return used;
  }

  // Twins ask the server the same question and get the same answer, so the
  // second one steps past whatever the first is already holding.
  function bumpPast(id, used) {
    var m = /^([AB])(\d{3})\/(\d{2})$/.exec(id || "");
    if (!m) return id;
    var seq = parseInt(m[2], 10);
    while (used.indexOf(m[1] + pad3(seq) + "/" + m[3]) !== -1 && seq < 999) seq += 1;
    return m[1] + pad3(seq) + "/" + m[3];
  }

  function suggestCalfNumber(tr) {
    var input = tr.querySelector(".c_tag");
    input.value = "";
    input.placeholder = "\u2026";
    api("suggest_animal_id", {
      sex: tr.querySelector(".c_sex").value,
      birth_date: el("cv_date").value || "",
    }).then(function (r) {
      if (r.error) { input.placeholder = r.error; return; }
      input.value = bumpPast(r.id, calfNumbersInForm(tr));
      input.dataset.gaps = (r.gaps || []).join(",");
    });
  }

  // On this form the year is the calving date's, so only the sequence is open
  // to change. Editing the year belongs where an existing animal is corrected.
  function editCalfNumber(tr) {
    var input = tr.querySelector(".c_tag");
    var m = /^([AB])(\d{3})\/(\d{2})$/.exec(input.value || "");
    if (!m) { toast("Pick the calf\u2019s sex and the calving date first.", true); return; }
    var gaps = (input.dataset.gaps || "").split(",").filter(Boolean);
    var hint = gaps.length
      ? "Free below the last one: " + gaps.slice(0, 12).join(", ") + "."
      : "Every number below the last one is used.";
    var want = window.prompt("Number for this calf in 20" + m[3] + " \u2014 " + hint,
                             String(parseInt(m[2], 10)));
    if (want === null) return;
    var n = parseInt(want, 10);
    if (!(n >= 1 && n <= 999)) { toast("A number runs from 1 to 999.", true); return; }
    var candidate = m[1] + pad3(n) + "/" + m[3];
    if (calfNumbersInForm(tr).indexOf(candidate) !== -1) {
      toast(candidate + " is already on another calf in this form.", true); return;
    }
    input.value = candidate;
  }

  function addCalfRow() {
    var tb = root.querySelector('[data-el="cv_calves"] tbody');
    var herds = (EV && EV.herds ? EV.herds : []).map(function (h) { return '<option value="' + esc(h.name) + '">' + esc(h.label) + "</option>"; }).join("");
    var tr = document.createElement("tr");
    tr.innerHTML =
      '<td><div class="ulo-idcell"><input class="ulo-in c_tag" readonly placeholder="assigning\u2026">' +
        '<button type="button" class="ulo-idedit" title="Change this number">\u270e</button></div></td>' +
      '<td><input class="ulo-in c_name" placeholder="Name"></td>' +
      '<td><select class="ulo-in c_sex"><option>Female</option><option>Male</option></select></td>' +
      '<td><input class="ulo-in c_wt" type="number" min="0" step="any"></td>' +
      '<td><select class="ulo-in c_herd"><option value="">\u2014</option>' + herds + "</select></td>" +
      '<td><button class="ulo-x">&times;</button></td>';
    tr.querySelector(".ulo-x").onclick = function () { tr.remove(); };
    tr.querySelector(".ulo-idedit").onclick = function () { editCalfNumber(tr); };
    // A bull calf is not the next heifer in the book, so the letter and the
    // number both follow the sex.
    tr.querySelector(".c_sex").addEventListener("change", function () { suggestCalfNumber(tr); });
    tb.appendChild(tr);
    suggestCalfNumber(tr);
  }

