  // ---- HUSBANDRY -----------------------------------------------------------
  // Dosing is entered PER ANIMAL. A deworming round over a herd is one issue out
  // of the store — 2 ml a cow across 119 cows is 238 ml on one line — but still
  // one clinical event per cow, because withdrawal dates are per cow. The server
  // does that fan-out; this form's job is to make the arithmetic visible before
  // anyone commits to it, and to refuse a round the store cannot cover.
  var HB = null, HB_DRUGS = [];
  function loadHusbandry() {
    wireBackdate("hb_date");
    api("husbandry_options", {}).then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      HB = r;
      HB_DRUGS = r.drug_items || [];
      fill(el("hb_type"), r.event_types, null);
      fill(el("hb_animal"), animOpts(r.animals), "Select animal…");
      fill(el("hb_animals"), animOpts(r.animals), null);
      fill(el("hb_herd"), (r.herds || []).map(function (h) {
        return { value: h.name, label: h.label + "  ·  " + h.heads + " head" };
      }), "Select herd…");
      fill(el("hb_warehouse"), r.warehouses, "Select store…");
      if (r.drug_warehouse) el("hb_warehouse").value = r.drug_warehouse;
      addDrugRow();
      syncDrugBox();
      syncTarget();
    });

    // Dehorning and hoof trimming consume nothing, so the drug table is hidden
    // rather than left there to be filled in and silently ignored.
    function syncDrugBox() {
      var takesDrugs = (HB && HB.drug_consuming_types || []).indexOf(el("hb_type").value) !== -1;
      el("hb_drugbox").style.display = takesDrugs ? "" : "none";
    }
    function syncTarget() {
      var mode = el("hb_target").value;
      el("hb_pick_animal").style.display = mode === "animal" ? "" : "none";
      el("hb_pick_herd").style.display = mode === "herd" ? "" : "none";
      el("hb_pick_some").style.display = mode === "some" ? "" : "none";
      recount();
    }
    el("hb_type").addEventListener("change", function () { syncDrugBox(); recount(); });
    el("hb_target").addEventListener("change", syncTarget);
    el("hb_animal").addEventListener("change", recount);
    el("hb_herd").addEventListener("change", recount);
    el("hb_animals").addEventListener("change", recount);
    el("hb_adddrug").addEventListener("click", function () { addDrugRow(); recount(); });

    // The store the issue draws from decides which drugs exist and how much of
    // each. Changing it re-prices the picker rather than leaving farm-wide
    // numbers on screen that this store cannot honour.
    el("hb_warehouse").addEventListener("change", function () {
      var wh = this.value;
      api("drugs_in_store", { warehouse: wh }).then(function (r) {
        if (r.error) { toast(r.error, true); return; }
        HB_DRUGS = r.drug_items || [];
        qa('[data-el="hb_drugs"] tbody tr').forEach(function (tr) {
          var keep = tr.querySelector(".d_item").value;
          tr.querySelector(".d_item").innerHTML = drugOptions();
          tr.querySelector(".d_item").value = keep;
        });
        recount();
      });
    });

    el("hb_submit").addEventListener("click", function () {
      var mode = el("hb_target").value;
      var payload = {
        event_type: el("hb_type").value, event_date: el("hb_date").value,
        remarks: el("hb_remarks").value, source_warehouse: el("hb_warehouse").value,
        drugs: drugRows(),
      };
      if (mode === "animal") {
        if (!el("hb_animal").value) { toast("Select an animal.", true); return; }
        payload.animal = el("hb_animal").value;
      } else if (mode === "herd") {
        if (!el("hb_herd").value) { toast("Select a herd.", true); return; }
        payload.herd = el("hb_herd").value;
      } else {
        var picked = selectedAnimals();
        if (!picked.length) { toast("Pick at least one animal.", true); return; }
        payload.animals = picked;
      }
      var btn = this; btn.disabled = true;
      api("create_husbandry_event", { payload: payload }).then(function (r) {
        btn.disabled = false;
        var se = r.stock_entry ? " · issued on " + esc(r.stock_entry) : "";
        var many = r.animals > 1 ? " for <b>" + r.animals + "</b> animals" : "";
        if (handle(r, esc(r.event_type || "Event") + " recorded" + many + " — <b>" + (r.name || "") + "</b>" + se + ".")) {
          qa('[data-el="hb_drugs"] tbody tr').forEach(function (tr) { tr.remove(); });
          addDrugRow(); el("hb_remarks").value = "";
          // Balances moved, so the picker is stale.
          el("hb_warehouse").dispatchEvent(new Event("change"));
        }
      });
    });
  }

  function selectedAnimals() {
    return Array.prototype.slice.call(el("hb_animals").selectedOptions || []).map(function (o) { return o.value; });
  }
  function targetCount() {
    var mode = el("hb_target").value;
    if (mode === "animal") return el("hb_animal").value ? 1 : 0;
    if (mode === "some") return selectedAnimals().length;
    var opt = el("hb_herd").selectedOptions[0];
    if (!opt || !el("hb_herd").value) return 0;
    var h = ((HB && HB.herds) || []).filter(function (x) { return x.name === el("hb_herd").value; })[0];
    return h ? h.heads : 0;
  }
  function drugOptions() {
    return '<option value="">—</option>' + HB_DRUGS.map(function (d) {
      return '<option value="' + esc(d.value) + '">' + esc(d.label) + "</option>";
    }).join("");
  }
  function drugRows() {
    var out = [];
    qa('[data-el="hb_drugs"] tbody tr').forEach(function (tr) {
      var item = tr.querySelector(".d_item").value;
      var qty = num(tr.querySelector(".d_qty").value);
      if (!item || qty <= 0) return;
      out.push({
        item_code: item, qty: qty,
        dosage: tr.querySelector(".d_dose").value,
        batch_no: tr.querySelector(".d_batch").value,
        withdrawal_days: tr.querySelector(".d_wd").value,
        source_warehouse: el("hb_warehouse").value,
      });
    });
    return out;
  }

  // Per-animal qty x head count, checked against this store's balance, before
  // anything is submitted. The server blocks a short round anyway; this is so
  // the user finds out while they can still change the number.
  function recount() {
    var n = targetCount(), short = [];
    qa('[data-el="hb_drugs"] tbody tr').forEach(function (tr) {
      var code = tr.querySelector(".d_item").value;
      var per = num(tr.querySelector(".d_qty").value);
      var total = per * n;
      var drug = HB_DRUGS.filter(function (d) { return d.value === code; })[0];
      var cell = tr.querySelector(".d_total");
      if (!code || !per) { cell.textContent = "—"; cell.className = "n d_total"; return; }
      cell.textContent = fmt(total) + " " + ((drug && drug.uom) || "");
      var over = drug && total > drug.qty + 1e-9;
      cell.className = "n d_total" + (over ? " short" : "");
      if (over) short.push({ name: (drug.item_name || code), need: total, have: drug.qty, uom: drug.uom || "" });
    });
    var box = el("hb_verdict");
    if (!n) { box.innerHTML = '<div class="ulo-pill mute">No animals selected yet</div>'; return; }
    if (short.length) {
      box.innerHTML = '<div class="ulo-pill short">Store is short: ' + short.map(function (s) {
        return esc(s.name) + " — need " + fmt(s.need) + " " + esc(s.uom) + ", has " + fmt(s.have);
      }).join("; ") + "</div>";
    } else {
      box.innerHTML = '<div class="ulo-pill ok">' + n + " animal" + (n === 1 ? "" : "s") +
        " — the store can cover this round</div>";
    }
  }

  function addDrugRow() {
    var tb = root.querySelector('[data-el="hb_drugs"] tbody');
    var tr = document.createElement("tr");
    tr.innerHTML =
      '<td><select class="ulo-in d_item">' + drugOptions() + "</select></td>" +
      '<td><input class="ulo-in d_qty" type="number" min="0" step="any" value="1"></td>' +
      '<td class="n d_total">—</td>' +
      '<td><input class="ulo-in d_dose" placeholder="e.g. 20 ml"></td>' +
      '<td><input class="ulo-in d_batch" placeholder="Batch"></td>' +
      '<td><input class="ulo-in d_wd" type="number" min="0" step="1"></td>' +
      '<td><button class="ulo-x">&times;</button></td>';
    tr.querySelector(".ulo-x").onclick = function () { tr.remove(); recount(); };
    tr.querySelector(".d_item").addEventListener("change", recount);
    tr.querySelector(".d_qty").addEventListener("input", recount);
    tb.appendChild(tr);
  }

  // ---- ABORTION ------------------------------------------------------------
  function loadAbortion() {
    wireBackdate("ab_date");
    ensureEvents().then(function (r) { if (!r.error) fill(el("ab_animal"), animOpts(r.animals), "Select animal…"); });
    // abortion_cause lives on Livestock Event, so it comes from event_options'
    // sibling health_options call rather than a second endpoint.
    ensureHealth().then(function (r) { if (!r.error) fill(el("ab_cause"), r.abortion_causes, "Select cause…"); });
    el("ab_submit").addEventListener("click", function () {
      if (!el("ab_cause").value) { toast("Select the cause of abortion.", true); return; }
      submit(this, "create_abortion_event", {
        animal: el("ab_animal").value, abortion_cause: el("ab_cause").value,
        event_date: el("ab_date").value, abortion_notes: el("ab_notes").value,
      }, "Abortion recorded — <b>%name%</b>.", ["ab_notes"]);
    });
  }

  // ---- WEIGHT --------------------------------------------------------------
  function loadWeight() {
    wireBackdate("wt_date");
    ensureWeight().then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      fill(el("wt_animal"), animOpts(r.animals), "Select animal…");
      fill(el("wt_method"), r.methods, "Select method…");
    });
    el("wt_submit").addEventListener("click", function () {
      if (!el("wt_animal").value) { toast("Select an animal.", true); return; }
      if (num(el("wt_kg").value) <= 0) { toast("Enter a weight greater than zero.", true); return; }
      var btn = this; btn.disabled = true;
      api("create_weight_record", { payload: {
        animal: el("wt_animal").value, weight_date: el("wt_date").value, method: el("wt_method").value,
        weight_kg: el("wt_kg").value, bcs: el("wt_bcs").value, heart_girth_cm: el("wt_girth").value,
        remarks: el("wt_remarks").value,
      } }).then(function (r) {
        btn.disabled = false;
        var gain = r.daily_gain_kg ? " · daily gain " + r.daily_gain_kg + " kg" : "";
        if (handle(r, "Weight recorded — <b>" + (r.name || "") + "</b> · " + (r.weight_kg || 0) + " kg" + gain + ".")) {
          ["wt_kg", "wt_bcs", "wt_girth", "wt_remarks"].forEach(function (n) { el(n).value = ""; });
        }
      });
    });
  }

  // ---- CHECK UP ------------------------------------------------------------
  function loadCheckup() {
    wireBackdate("cu_date");
    loadCheckupDrugs();
    ensureHealth().then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      fill(el("cu_animal"), animOpts(r.animals), "Select animal…");
      fill(el("cu_appearance"), r.appearances, "—");
      fill(el("cu_hydration"), r.hydrations, "—");
      fill(el("cu_action"), r.actions, "Select action…");
      fill(el("cu_disease"), r.diseases, "—");
    });
    el("cu_submit").addEventListener("click", function () {
      if (!el("cu_action").value) { toast("Select the action taken.", true); return; }
      submit(this, "create_check_up", {
        animal: el("cu_animal").value, diagnosis_date: el("cu_date").value,
        reason_for_check: el("cu_reason").value, appearance: el("cu_appearance").value,
        hydration: el("cu_hydration").value, temperature_c: el("cu_temp").value,
        respiration_rate: el("cu_resp").value, heart_rate: el("cu_hr").value,
        bcs: el("cu_bcs").value, lameness_score: el("cu_lame").value,
        suggested_disease: el("cu_disease").value, action_taken: el("cu_action").value,
        action_notes: el("cu_notes").value, follow_up_date: el("cu_followup").value,
        drugs: cuRows(),
      }, "Check up recorded — <b>%name%</b>.",
        ["cu_reason", "cu_temp", "cu_resp", "cu_hr", "cu_bcs", "cu_lame", "cu_notes"]);
    });
  }

  // ---- TREATMENTS (on an open health case) ---------------------------------
  // Kept out of the Health Case card deliberately: opening a case and treating
  // one are different acts on different days. The store balance shown is the
  // drug store's, and a line it cannot cover is flagged before submit.
  var TX = null, TX_DRUGS = [];
  function loadTreatment() {
    wireBackdate("tx_date");
    api("open_health_cases", {}).then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      TX = r;
      TX_DRUGS = r.drug_items || [];
      fill(el("tx_case"), r.cases, r.cases.length ? "Select case…" : "No open cases");
      addTxRow();
    });
    el("tx_adddrug").addEventListener("click", function () { addTxRow(); txRecount(); });
    el("tx_submit").addEventListener("click", function () {
      if (!el("tx_case").value) { toast("Select a case.", true); return; }
      var rows = txRows();
      if (!rows.length) { toast("Add at least one drug.", true); return; }
      var btn = this; btn.disabled = true;
      api("add_case_treatment", { payload: {
        case: el("tx_case").value, treatment_date: el("tx_date").value,
        treatments: rows.map(function (t) { return Object.assign({ notes: el("tx_notes").value }, t); }),
      } }).then(function (r) {
        btn.disabled = false;
        var se = r.stock_entry ? " · issued on " + esc(r.stock_entry) : "";
        if (handle(r, "Treatment recorded on <b>" + esc(r.name || "") + "</b>" + se + ".")) {
          qa('[data-el="tx_drugs"] tbody tr').forEach(function (tr) { tr.remove(); });
          addTxRow(); el("tx_notes").value = "";
          api("open_health_cases", {}).then(function (rr) {
            if (!rr.error) { TX_DRUGS = rr.drug_items || []; txRecount(); }
          });
        }
      });
    });
  }
  function txRows() {
    var out = [];
    qa('[data-el="tx_drugs"] tbody tr').forEach(function (tr) {
      var item = tr.querySelector(".t_item").value;
      var qty = num(tr.querySelector(".t_qty").value);
      if (!item || qty <= 0) return;
      out.push({
        drug_item: item, qty: qty,
        dosage: tr.querySelector(".t_dose").value,
        route: tr.querySelector(".t_route").value,
        withdrawal_period_days: tr.querySelector(".t_wd").value,
      });
    });
    return out;
  }
  function txRecount() {
    var short = [];
    txRows().forEach(function (t) {
      var drug = TX_DRUGS.filter(function (d) { return d.value === t.drug_item; })[0];
      if (drug && t.qty > drug.qty + 1e-9) {
        short.push({ name: drug.item_name || t.drug_item, need: t.qty, have: drug.qty, uom: drug.uom || "" });
      }
    });
    var box = el("tx_verdict");
    box.innerHTML = short.length
      ? '<div class="ulo-pill short">Store is short: ' + short.map(function (s) {
          return esc(s.name) + " — need " + fmt(s.need) + " " + esc(s.uom) + ", has " + fmt(s.have);
        }).join("; ") + "</div>"
      : "";
  }
  function addTxRow() {
    var tb = root.querySelector('[data-el="tx_drugs"] tbody');
    var opts = '<option value="">—</option>' + TX_DRUGS.map(function (d) {
      return '<option value="' + esc(d.value) + '">' + esc(d.label) + "</option>";
    }).join("");
    var routes = '<option value="">—</option>' + (((TX && TX.routes) || [])).map(function (r) {
      return '<option value="' + esc(r) + '">' + esc(r) + "</option>";
    }).join("");
    var tr = document.createElement("tr");
    tr.innerHTML =
      '<td><select class="ulo-in t_item">' + opts + "</select></td>" +
      '<td><input class="ulo-in t_qty" type="number" min="0" step="any" value="1"></td>' +
      '<td><input class="ulo-in t_dose" placeholder="e.g. 20 ml"></td>' +
      '<td><select class="ulo-in t_route">' + routes + "</select></td>" +
      '<td><input class="ulo-in t_wd" type="number" min="0" step="1"></td>' +
      '<td><button class="ulo-x">&times;</button></td>';
    tr.querySelector(".ulo-x").onclick = function () { tr.remove(); txRecount(); };
    tr.querySelector(".t_item").addEventListener("change", txRecount);
    tr.querySelector(".t_qty").addEventListener("input", txRecount);
    tb.appendChild(tr);
  }

  // ---- CHECK UP drug rows --------------------------------------------------
  // A routine check that turns into a treatment used to move no stock at all.
  var CU_DRUGS = [];
  function loadCheckupDrugs() {
    api("drugs_in_store", {}).then(function (r) {
      if (r.error) return;
      CU_DRUGS = r.drug_items || [];
      addCuRow();
    });
    el("cu_adddrug").addEventListener("click", function () { addCuRow(); cuRecount(); });
  }
  function cuRows() {
    var out = [];
    qa('[data-el="cu_drugs"] tbody tr').forEach(function (tr) {
      var item = tr.querySelector(".c_item").value;
      var qty = num(tr.querySelector(".c_qty").value);
      if (!item || qty <= 0) return;
      out.push({
        item_code: item, qty: qty,
        dosage: tr.querySelector(".c_dose").value,
        batch_no: tr.querySelector(".c_batch").value,
        withdrawal_days: tr.querySelector(".c_wd").value,
      });
    });
    return out;
  }
  function cuRecount() {
    var short = [];
    cuRows().forEach(function (t) {
      var drug = CU_DRUGS.filter(function (d) { return d.value === t.item_code; })[0];
      if (drug && t.qty > drug.qty + 1e-9) {
        short.push({ name: drug.item_name || t.item_code, need: t.qty, have: drug.qty, uom: drug.uom || "" });
      }
    });
    var box = el("cu_verdict");
    box.innerHTML = short.length
      ? '<div class="ulo-pill short">Store is short: ' + short.map(function (s) {
          return esc(s.name) + " — need " + fmt(s.need) + " " + esc(s.uom) + ", has " + fmt(s.have);
        }).join("; ") + "</div>"
      : "";
  }
  function addCuRow() {
    var tb = root.querySelector('[data-el="cu_drugs"] tbody');
    var opts = '<option value="">—</option>' + CU_DRUGS.map(function (d) {
      return '<option value="' + esc(d.value) + '">' + esc(d.label) + "</option>";
    }).join("");
    var tr = document.createElement("tr");
    tr.innerHTML =
      '<td><select class="ulo-in c_item">' + opts + "</select></td>" +
      '<td><input class="ulo-in c_qty" type="number" min="0" step="any" value="1"></td>' +
      '<td><input class="ulo-in c_dose" placeholder="e.g. 20 ml"></td>' +
      '<td><input class="ulo-in c_batch" placeholder="Batch"></td>' +
      '<td><input class="ulo-in c_wd" type="number" min="0" step="1"></td>' +
      '<td><button class="ulo-x">&times;</button></td>';
    tr.querySelector(".ulo-x").onclick = function () { tr.remove(); cuRecount(); };
    tr.querySelector(".c_item").addEventListener("change", cuRecount);
    tr.querySelector(".c_qty").addEventListener("input", cuRecount);
    tb.appendChild(tr);
  }

  // ---- HEALTH CASE ---------------------------------------------------------
  function loadHealthCase() {
    wireBackdate("hc_date");
    loadTreatment();
    ensureHealth().then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      fill(el("hc_animal"), animOpts(r.animals), "Select animal…");
      fill(el("hc_status"), r.case_statuses, null);
      fill(el("hc_severity"), r.severities, "—");
      fill(el("hc_disease"), r.diseases, "—");
    });
    el("hc_submit").addEventListener("click", function () {
      if (!el("hc_symptoms").value.trim()) { toast("Describe the presenting symptoms.", true); return; }
      submit(this, "create_health_case", {
        animal: el("hc_animal").value, opened_date: el("hc_date").value,
        case_status: el("hc_status").value, severity: el("hc_severity").value,
        presenting_symptoms: el("hc_symptoms").value, body_systems: el("hc_systems").value,
        provisional_diagnosis: el("hc_disease").value,
        vet_called: el("hc_vetcalled").value, vet_name: el("hc_vetname").value,
      }, "Case opened — <b>%name%</b>.", ["hc_symptoms", "hc_systems", "hc_vetname"]);
    });
  }

  // ---- DISPOSAL ------------------------------------------------------------
  function loadDisposal() {
    wireBackdate("dp_date");
    ensureDisposal().then(function (r) {
      if (r.error) { toast(r.error, true); return; }
      fill(el("dp_animal"), animOpts(r.animals), "Select animal…");
      fill(el("dp_type"), r.disposal_types, "Select…");
      fill(el("dp_customer"), r.customers, "—");
      syncSaleRow();
    });
    // Customer / price / buyer only mean anything for a sale; the server skips the
    // sale posting (with a warning) when either is missing, so hiding them for the
    // other disposal types keeps the form honest about what it will do.
    function syncSaleRow() {
      var isSale = el("dp_type").value === "Sold";
      var row = el("dp_salerow");
      if (row) row.style.display = isSale ? "" : "none";
    }
    el("dp_type").addEventListener("change", syncSaleRow);
    el("dp_submit").addEventListener("click", function () {
      var animal = el("dp_animal").value, type = el("dp_type").value;
      if (!animal) { toast("Select an animal.", true); return; }
      if (!type) { toast("Select how the animal left the herd.", true); return; }
      var label = el("dp_animal").options[el("dp_animal").selectedIndex].text;
      if (!window.confirm("Dispose of " + label + " as \"" + type + "\"?\n\nThis permanently disables the animal and posts the asset sale or scrap. It cannot be undone from this form.")) return;
      var btn = this; btn.disabled = true;
      api("record_disposal", { payload: {
        animal: animal, disposal_type: type, disposal_date: el("dp_date").value,
        customer: el("dp_customer").value, sale_price: el("dp_price").value,
        buyer_name: el("dp_buyer").value, reason_details: el("dp_reason").value,
        witness: el("dp_witness").value,
      } }).then(function (r) {
        btn.disabled = false;
        if (handle(r, "Disposal recorded — <b>" + (r.name || "") + "</b> · animal now " + esc(r.animal_status || "") + ".")) {
          ["dp_price", "dp_buyer", "dp_reason", "dp_witness"].forEach(function (n) { el(n).value = ""; });
          // The animal is gone from every active list — drop the caches so the
          // next tab visit re-fetches instead of offering a disabled animal.
          evP = null; brP = null; listsP = null; healthP = null; weightP = null; dispP = null;
          loaded = { disposal: true };
          ensureDisposal().then(function (rr) { if (!rr.error) fill(el("dp_animal"), animOpts(rr.animals), "Select animal…"); });
        }
      });
    });
  }

  // boot — Feed tab is active by default
  loadFeed(); loaded.feed = true;
})();

style:
/* Livestock Operations — styled to doc references/design/ufd-modern-4-livestock.html.
   Poppins is registered at document level via app_include_css (livestock_fonts.css)
   because @font-face inside a Custom HTML Block's shadow DOM is ignored. */
.ulo{
  --ink:#0a0a0a;--ink-1:#1a1a18;--ink-2:#2a2a26;--ink-3:#3a3a34;--ink-4:#5a5a52;
  --ink-mute:#8a8780;--ink-faint:#b8b6ae;
  --bg:#f4f3ef;--surface:#fafaf6;--surface-2:#ffffff;--hairline:rgba(10,10,10,0.06);
  --line:rgba(10,10,10,0.10);
  --shadow-card:0 1px 0 rgba(10,10,10,0.04),0 8px 32px -16px rgba(10,10,10,0.10);
  --shadow-hover:0 1px 0 rgba(10,10,10,0.06),0 24px 48px -24px rgba(10,10,10,0.18);
  --signal:#228883;--danger:#c4302b;
  --grad-ink:linear-gradient(135deg,#0a0a0a 0%,#3a3a34 100%);
  --sans:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  font-family:var(--sans);color:var(--ink-3);line-height:1.55;
  -webkit-font-smoothing:antialiased;padding:8px 4px 40px;position:relative;
}
.ulo *{box-sizing:border-box}

/* PAGEHEAD */
.ulo-head{margin:0 0 28px}
.ulo-eyebrow{font:500 11px var(--sans);text-transform:uppercase;letter-spacing:2.2px;color:var(--ink-mute);margin-bottom:10px;display:inline-flex;align-items:center;gap:10px}
.ulo-eyebrow::before{content:"";width:18px;height:1px;background:var(--ink-3)}
.ulo-title{font:600 40px/1.05 var(--sans);color:var(--ink);letter-spacing:-1.2px;margin:0}
.ulo-sub{margin-top:8px;font-size:15px;color:var(--ink-4)}

/* TABS — reference black pills in a tinted rail */
.ulo-tabs{display:inline-flex;gap:4px;margin-bottom:28px;background:rgba(10,10,10,0.04);padding:5px;border-radius:999px;max-width:100%;overflow-x:auto;vertical-align:top}
.ulo-tab{background:transparent;border:0;font:500 13px var(--sans);color:var(--ink-4);padding:10px 18px;border-radius:999px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;white-space:nowrap;transition:all .2s}
.ulo-tab svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;flex:none}
.ulo-tab:hover{color:var(--ink)}
.ulo-tab.on{background:var(--grad-ink);color:#fafaf6;box-shadow:0 4px 14px rgba(10,10,10,0.20)}

.ulo-panel{display:none;animation:ulofade .28s ease}
.ulo-panel.on{display:block}
@keyframes ulofade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

/* CARDS */
.ulo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:18px;margin-bottom:18px}
.ulo-card{background:var(--surface-2);border-radius:24px;padding:28px 32px;box-shadow:var(--shadow-card);transition:box-shadow .25s}
.ulo-card:hover{box-shadow:var(--shadow-hover)}
.ulo-card-title{font:600 18px var(--sans);color:var(--ink);letter-spacing:-.4px;margin-bottom:3px}
.ulo-card-sub{font:400 13px var(--sans);color:var(--ink-mute);margin-bottom:16px}

/* FORM FIELDS */
.ulo-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;margin-bottom:2px}
.ulo-lbl{display:block;font:500 10.5px var(--sans);letter-spacing:1px;text-transform:uppercase;color:var(--ink-mute);margin:14px 0 6px}
.ulo-in{width:100%;font-family:var(--sans);font-size:13px;color:var(--ink);background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:10px 13px;outline:none;transition:border-color .15s,box-shadow .15s}
.ulo-in:focus{border-color:var(--signal);box-shadow:0 0 0 3px rgba(34,136,131,.12)}
select.ulo-in{cursor:pointer}
.ulo-calc{font:600 14px var(--sans);color:var(--signal);padding:10px 0}

/* PORTION SWITCH (feed run: half day / full day) */
.ulo-portion{min-width:220px}
.ulo-portion-track{display:flex;align-items:center;gap:12px}
.ulo-portion-end{font:500 10.5px var(--sans);letter-spacing:.5px;color:var(--ink-mute);white-space:nowrap;transition:color .15s,font-weight .15s}
.ulo-portion-end.active{color:var(--signal);font-weight:700}
.ulo-switch{flex:none;position:relative;width:58px;height:32px;padding:3px;border:0;border-radius:999px;background:var(--line);cursor:pointer;outline:none;transition:background-color .2s ease-out}
.ulo-switch[aria-checked="true"]{background:var(--signal)}
.ulo-switch:focus-visible{box-shadow:0 0 0 4px rgba(34,136,131,.20)}
.ulo-switch-thumb{display:block;width:26px;height:26px;border-radius:50%;background:var(--surface-2);box-shadow:0 2px 8px rgba(10,10,10,0.25);transition:transform .24s cubic-bezier(.2,.8,.2,1)}
.ulo-switch[aria-checked="true"] .ulo-switch-thumb{transform:translateX(26px)}
.ulo-portion-qty{font:600 13px var(--sans);color:var(--ink-2);margin-top:10px}
.ulo-portion-qty b{color:var(--signal)}

/* BUTTONS */
.ulo-btn{margin-top:20px;font:600 13px var(--sans);color:#fafaf6;background:var(--grad-ink);border:none;border-radius:999px;padding:12px 24px;cursor:pointer;box-shadow:0 4px 14px rgba(10,10,10,0.18);transition:transform .05s,box-shadow .2s,opacity .15s}
.ulo-btn:hover{box-shadow:var(--shadow-hover)}
.ulo-btn:active{transform:translateY(1px)}
.ulo-btn:disabled{opacity:.4;cursor:not-allowed;box-shadow:none}
.ulo-btn.ghost{background:rgba(10,10,10,0.04);color:var(--ink-4);border:0;box-shadow:none;margin-top:10px;padding:8px 16px}
.ulo-btn.ghost:hover{background:var(--ink);color:#fafaf6}

/* PREVIEW rows (feed) */
.ulo-preview{margin:16px 0 4px;font-size:12.5px;color:var(--ink-4)}
.ulo-preview .h{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--hairline)}
.ulo-preview .h:last-child{border-bottom:0}
.ulo-preview .h b{color:var(--ink);font-variant-numeric:tabular-nums}
.ulo-preview .warn{color:var(--danger)}

/* TABLES */
.ulo-table{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px}
.ulo-table th{text-align:left;font:600 10px var(--sans);color:var(--ink-mute);text-transform:uppercase;letter-spacing:.06em;padding:7px 8px;border-bottom:1px solid var(--hairline)}
.ulo-table td{padding:6px;border-bottom:1px solid var(--hairline);vertical-align:middle}
.ulo-table .ulo-in{padding:7px 9px;font-size:12px;border-radius:9px}
.ulo-x{cursor:pointer;color:var(--ink-mute);font-size:17px;line-height:1;border:none;background:none;padding:0 6px}
.ulo-x:hover{color:var(--danger)}

/* WORKLISTS */
.ulo-list{font-size:12.5px}
.ulo-list .r{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--hairline)}
.ulo-list .r:last-child{border-bottom:0}
.ulo-list .r .m{color:var(--ink-mute);font-size:11px}
.ulo-empty{color:var(--ink-mute);font-size:12px;padding:12px 0}

/* TOAST */
.ulo-toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);max-width:560px;background:var(--ink);color:#fafaf6;border-radius:14px;padding:14px 20px;font-size:13px;box-shadow:0 24px 48px -24px rgba(10,10,10,.5);opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;z-index:99999}
.ulo-toast.show{opacity:1;transform:translate(-50%,0);pointer-events:auto}
.ulo-toast.err{background:var(--danger)}
.ulo-toast b{color:#fff}
.ulo-toast .cx{float:right;margin-left:16px;cursor:pointer;opacity:.7}

@media (max-width:900px){.ulo-title{font-size:32px}.ulo-card{padding:22px 20px}}

/* Warning variant of the card subtitle — used by the Disposal tab, whose action
   is irreversible. */
.ulo .ulo-card-sub.ulo-warn {
  color: #9a3412;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  padding: 8px 10px;
}

/* FEEDING PROGRAMME */
.ulo-headline{display:flex;flex-wrap:wrap;align-items:baseline;gap:10px 22px;margin:18px 0 4px}
.ulo-headline .k{font:500 10.5px var(--sans);letter-spacing:1px;text-transform:uppercase;color:var(--ink-mute);display:block;margin-bottom:2px}
.ulo-headline .v{font:600 20px var(--sans);color:var(--ink);letter-spacing:-.5px;font-variant-numeric:tabular-nums}
.ulo-headline .v small{font-size:12px;font-weight:500;color:var(--ink-mute);margin-left:3px}
.ulo-pill{display:inline-flex;align-items:center;gap:7px;font:600 11.5px var(--sans);border-radius:999px;padding:7px 15px;margin:14px 0 2px}
.ulo-pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.ulo-pill.ok{background:rgba(34,136,131,.10);color:var(--signal)}
.ulo-pill.short{background:rgba(196,48,43,.09);color:var(--danger)}
.ulo-tag{display:inline-block;font:600 9.5px var(--sans);letter-spacing:.09em;text-transform:uppercase;color:var(--ink-4);background:rgba(10,10,10,.05);border-radius:999px;padding:3px 8px;margin-left:7px;vertical-align:1px}
.ulo-table td.n,.ulo-table th.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.ulo-table td.short{color:var(--danger);font-weight:600}
.ulo-table td.wh{color:var(--ink-mute);font-size:11px}
.ulo-table tr.is-short td{background:rgba(196,48,43,.035)}
.ulo-note{font-size:11.5px;color:var(--ink-mute);margin-top:10px}
.ulo-sec{font:500 11px var(--sans);letter-spacing:2.2px;text-transform:uppercase;color:var(--ink-mute);margin:26px 0 12px;display:flex;align-items:center;gap:10px}
.ulo-sec::before{content:"";width:18px;height:1px;background:var(--ink-3);flex:none}
.ulo-inline{display:flex;flex-wrap:wrap;align-items:flex-end;gap:12px}
.ulo-inline .ulo-btn{margin-top:0}
.ulo-inline .qty{width:150px}
.ulo-inline .qty .ulo-lbl{margin-top:0}
.ulo-table .alt{color:var(--ink-faint);font-size:10.5px;font-weight:500}
.ulo-pill.mute{background:rgba(10,10,10,.05);color:var(--ink-4)}
/* MULTI-SELECT + HINTS */
.ulo-hint{font:400 10px var(--sans);letter-spacing:0;text-transform:none;color:var(--ink-faint)}
.ulo-multi{height:auto;padding:6px}
.ulo-multi option{padding:5px 7px;border-radius:7px}
.ulo-count{font:600 12px var(--sans);color:var(--ink);font-variant-numeric:tabular-nums}

/* SUB-TABS — Feed's System / Manual configuration split */
.ulo-subtabs{display:inline-flex;gap:4px;margin:8px 0 18px;background:rgba(10,10,10,0.04);padding:4px;border-radius:999px}
.ulo-subtab{background:transparent;border:0;font:500 12px var(--sans);color:var(--ink-4);padding:8px 16px;border-radius:999px;cursor:pointer;transition:all .2s}
.ulo-subtab:hover{color:var(--ink)}
.ulo-subtab.on{background:var(--grad-ink);color:#fafaf6}

/* BACKDATING — amber, deliberately outside the ink/signal palette used
   everywhere else in this block: this is the one control that takes an
   operator somewhere the normal rules (today only, no stock effect) do not
   apply, and it should not read as one more neutral form field. */
.ulo-bd-btn{font:600 11px var(--sans);color:#B45309;background:rgba(180,83,9,.08);border:1px solid #B45309;border-radius:999px;padding:9px 16px;margin:14px 0 0;cursor:pointer;transition:all .15s;white-space:nowrap}
.ulo-bd-btn:hover{background:#B45309;color:#fff}
.ulo-bd-btn.on{background:#B45309;color:#fff}
.ulo-bd-warn{font:500 12px var(--sans);color:#B45309;background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:10px 14px;margin:2px 0 4px}

/* MANUAL FEEDING — a different warning, about accountability rather than
   backdating, but the same amber: both mean the usual safety net is off. */
.ulo-manual-warn{font:500 12.5px var(--sans);color:#B45309;background:#fffbeb;border:1px solid #fde68a;border-radius:10px;padding:12px 16px;margin:2px 0 16px}
.ulo-manual-row{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.ulo-manual-row .name{flex:1;font-size:12.5px;color:var(--ink-3)}
.ulo-manual-row .ulo-in{width:130px}


/* RECIPE PICKER — the detail strip under the select. The per-head figure is
   the loudest thing in it: it is what separates two recipes with the same
   name and a twelvefold difference in what they feed. */
.ulo-recipe{margin-top:10px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 14px}
.ulo-recipe .hd{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px}
.ulo-recipe .hd b{font:700 13px var(--sans);color:var(--signal);font-variant-numeric:tabular-nums}
.ulo-recipe .hd .ulo-tag{margin-left:0}
.ulo-recipe .m{font-size:11.5px;color:var(--ink-mute);margin-top:6px}
/* A recipe far from what this herd is usually fed. Danger red, not the amber
   used for backdating: this one is a wrong quantity about to go in a trough. */
.ulo-recipe-warn{margin-top:8px;font:600 12px var(--sans);color:var(--danger);background:rgba(196,48,43,.07);border:1px solid rgba(196,48,43,.25);border-radius:10px;padding:9px 12px}
.ulo-recipe-warn::before{content:"⚠ ";}
.ulo-warn-note{color:#B45309}

/* LIVE INGREDIENT SEARCH — a panel rather than a datalist, so what is already
   on the recipe can be kept out of it as the operator types. */
.ulo-suggest-wrap{position:relative}
.ulo-suggest{position:absolute;left:0;right:0;top:100%;z-index:40;margin-top:4px;max-height:240px;overflow-y:auto;background:var(--surface-2);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow-hover);padding:5px}
.ulo-suggest button{display:block;width:100%;text-align:left;border:0;background:none;border-radius:9px;padding:7px 9px;font:500 12.5px var(--sans);color:var(--ink-2);cursor:pointer}
.ulo-suggest button:hover{background:rgba(10,10,10,.05)}
.ulo-suggest button .c{display:block;font:400 10.5px var(--sans);color:var(--ink-faint);margin-top:1px}
.ulo-suggest .m{padding:8px 9px;font-size:12px;color:var(--ink-mute)}

/* ROW EXPANDERS — what went in the mixer, revealed in place. */
.ulo-table th.x,.ulo-table td.x{width:24px;padding-left:0;padding-right:0}
.ulo-exp{border:0;background:none;cursor:pointer;color:var(--ink-mute);font-size:12px;line-height:1;padding:3px 4px;border-radius:6px}
.ulo-exp:hover{color:var(--ink);background:rgba(10,10,10,.05)}
.ulo-exp-row>td{background:rgba(10,10,10,.025);padding:4px 10px 10px}
.ulo-exp-row .ulo-table{margin-top:4px}

.ulo-idcell { display: flex; align-items: center; gap: 4px; }
.ulo-idcell .c_tag { font-variant-numeric: tabular-nums; letter-spacing: .02em; background: rgba(0,0,0,.03); }
.ulo-idedit { border: 0; background: transparent; cursor: pointer; padding: 2px 4px; opacity: .55; font-size: 13px; line-height: 1; }
.ulo-idedit:hover { opacity: 1; }
